import './ProfilePage.css'
import UserSide from '../../components/UserSide/UserSide'
import ShareSide from '../../components/ShareSide/ShareSide'
import PeopleYouKnowSide from '../../components/PeopleYouKnowSide/PeopleYouKnowSide'
import { useEffect, useState } from 'react';


const ProfilePage = ({ User_Data, Loged_User_Data }) => {
  
  const login = async () => {
    // Шаг 1: Получить CSRF-cookie от Laravel Sanctum
    await fetch('http://localhost:8000/sanctum/csrf-cookie', {
      credentials: 'include',
    });
  
    // Шаг 2: Отправить логин-запрос
    const response = await fetch('http://localhost:8000/api/login', {
      method: 'POST',
      credentials: 'include', // для cookie
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
      },
      body: JSON.stringify({
        email: 'test@example.com',   // <-- заменишь на данные из формы
        password: 'password',        // <-- тоже заменишь на свои данные
      }),
    });
  
    if (response.ok) {
      const user = await response.json();
      console.log('Вход успешен:', user);
      return user; // возвращаем пользователя в React
    } else {
      console.log('Ошибка входа');
      return null;
    }
  };

  const handleLogin = () => {
    login().then(setUser);
  };
  return (
    <header className="ProfilePage">
      <UserSide User_Data={User_Data} Loged_User_Data={Loged_User_Data} />
      <ShareSide />
      <PeopleYouKnowSide />
    </header>
  );
};

export default ProfilePage
